<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {api,errorMessage} from '../api/http'
const route=useRoute(),router=useRouter(),detail=ref<any>(null),busy=ref(true),failure=ref('')
const id=String(route.params.id)
async function load(){busy.value=true;failure.value='';try{detail.value=await api('/exports/'+id)}catch(e){failure.value=errorMessage(e)}finally{busy.value=false}}
const exp=computed(()=>detail.value?.export||{})
const packing=computed(()=>detail.value?.items?.flatMap((it:any)=>it.packing||[])||[])
const weight=computed(()=>packing.value.reduce((s:number,p:any)=>s+Number(p.gross_weight_kg||0),0))
const vol=computed(()=>packing.value.reduce((s:number,p:any)=>s+Number(p.volume_m3||0),0))
onMounted(load)
</script>
<template><template v-if="busy"><div class="page-loading">読み込み中...</div></template><template v-else-if="detail"><h1 class="page-title">輸出詳細</h1><div class="toolbar"><el-button class="back" @click="router.push('/exports')">← 一覧に戻る</el-button><el-button type="primary" @click="router.push('/exports/'+id+'/documents')">原票を見る</el-button></div><section class="panel"><header class="panel-heading">基本情報</header><div class="panel-body"><el-descriptions :column="2" border><el-descriptions-item label="輸出No.">{{exp.export_no}}</el-descriptions-item><el-descriptions-item label="取引先">{{exp.customer_name}}</el-descriptions-item><el-descriptions-item label="出荷日">{{exp.export_date||'—'}}</el-descriptions-item><el-descriptions-item label="契約No.">{{exp.contract_no||'—'}}</el-descriptions-item><el-descriptions-item label="Invoice No.">{{detail.invoices.map((i:any)=>i.invoice_no).join(', ')||'—'}}</el-descriptions-item><el-descriptions-item label="状態">{{exp.export_status}}</el-descriptions-item></el-descriptions></div></section><section class="panel"><header class="panel-heading">設備・包装明細</header><div class="panel-body"><div v-for="item in detail.items" :key="item.export_item_id" style="margin-bottom:20px"><div class="summary"><b>{{item.equipment_name}}</b>　型番: {{item.model_no||'—'}}　メーカー: {{item.manufacturer||'—'}}　数量: {{item.quantity}}</div><div class="scrollable-table"><el-table :data="item.packing" border size="small"><el-table-column prop="part_code" label="符号" width="80"/><el-table-column prop="part_name" label="分解部品" min-width="150"/><el-table-column prop="pcs" label="PCS" width="70"/><el-table-column prop="length_mm" label="長さ mm" width="115"/><el-table-column prop="width_mm" label="幅 mm" width="105"/><el-table-column prop="height_mm" label="高さ mm" width="105"/><el-table-column prop="gross_weight_kg" label="重量 kg" width="110"/><el-table-column prop="volume_m3" label="容積 m³" width="110"/></el-table></div></div><div class="inline-stats"><el-tag type="info">包装行: {{packing.length}}</el-tag><el-tag type="info">行重量計: {{weight.toFixed(3)}} kg</el-tag><el-tag type="info">行体積計: {{vol.toFixed(3)}} m³</el-tag></div><p class="data-note">明細の数値は行単位の登録値として表示。実際の重量/体積の単位・数量解釈は原票と照合してください。</p><el-table :data="detail.packingHeaders" size="small" border style="margin-top:14px"><el-table-column label="Packing List" prop="packing_no"/><el-table-column prop="package_count_reported" label="原票の総件数"/><el-table-column prop="total_gross_weight_kg_reported" label="原票の総重量 kg"/><el-table-column prop="total_volume_m3_reported" label="原票の総容積 m³"/></el-table></div></section><section class="panel"><header class="panel-heading">コンテナ情報</header><div class="panel-body"><el-table :data="detail.containers" border><el-table-column prop="container_type" label="箱種"/><el-table-column prop="container_qty" label="数量"/><el-table-column label="記録根拠"><template #default="s"><el-tag :type="s.row.record_basis==='ACTUAL'?'success':s.row.record_basis==='PLANNED'?'warning':'info'">{{s.row.record_basis}}</el-tag></template></el-table-column><el-table-column prop="source_text" label="資料・備考"/></el-table><div class="data-note">ACTUAL は実際の出荷根拠が確認できた場合のみ使用してください。</div></div></section><section class="panel"><header class="panel-heading">出荷スケジュール</header><div class="panel-body"><el-descriptions :column="2" border><el-descriptions-item label="出港地">{{exp.ship_from||'—'}}</el-descriptions-item><el-descriptions-item label="到着地">{{exp.ship_to||'—'}}</el-descriptions-item><el-descriptions-item label="船名">{{exp.vessel||'—'}}</el-descriptions-item><el-descriptions-item label="ETD">{{exp.etd_date||'—'}}</el-descriptions-item><el-descriptions-item label="ETA">{{exp.eta_date||'—'}}</el-descriptions-item></el-descriptions></div></section><section class="panel"><header class="panel-heading">関連書類</header><div class="panel-body"><el-button type="primary" @click="router.push('/exports/'+id+'/documents')">原票プレビュー（{{detail.documents.length}} 件）</el-button></div></section></template><el-result v-else icon="error" title="詳細を読み込めません" :sub-title="failure"><template #extra><el-button @click="load">再試行</el-button><el-button @click="router.push('/exports')">一覧に戻る</el-button></template></el-result></template>
